INSERT INTO `wp_posts` VALUES (1532,0,'2026-05-20 01:44:52','2026-05-20 01:44:52','<div class=\"ast-accordion-wrap\"><h2>Mô tả thông số kỹ thuật của Bàn đông FT-156MA-S – Hoshizaki</h2>\n<table class=\"specifications\"><tbody><tr><td>Product Series</td><td>UNDERCOUNTER, Freezer</td></tr>\n<tr><td>Model Name</td><td>FT-156MA-S</td></tr>\n<tr><td>Net Weight (kg)</td><td>81</td></tr>\n<tr><td>Gross Weight Packed (kg)</td><td>86</td></tr>\n<tr><td>Electric Connection Load (kW)</td><td>0.415</td></tr>\n<tr><td>Outside Dimensions W x D x H (mm)</td><td>1500 x 600 x 850</td></tr>\n<tr><td>Refrigerant</td><td>R134a</td></tr>\n<tr><td>Temperature setting</td><td>-23°C to -7°C</td></tr>\n<tr><td>Effective Storage Capacity (L)</td><td>318</td></tr>\n<tr><td>Number of Shelves (Pcs)</td><td>4</td></tr>\n<tr><td>Cooling System</td><td>Air Cooled</td></tr>\n</tbody></table>\n<p><img class=\"alignnone wp-image-14450 size-full\" alt=\"Bàn đông FT-156MA-S - Hoshizaki\" width=\"500\" height=\"600\" src=\"https://saigonhoreca.vn/wp-content/uploads/2023/12/undercounter-freezer-ft-126ma-s.jpg\"></p>\n</div>\n','Bàn đông FT-156MA-S - Hoshizaki','','publish','closed','closed','','ban-dong-ft-156ma-s-hoshizaki','','','2026-05-20 09:54:12','2026-05-20 09:54:12','',0,'https://saigonhoreca.local/san-pham/ban-dong-ft-156ma-s-hoshizaki/',0,'product','',0);
