INSERT INTO `wp_posts` VALUES (1733,0,'2026-05-20 02:20:14','2026-05-20 02:20:14','<div class=\"elementor elementor-24293\" data-elementor-id=\"24293\" data-elementor-post-type=\"page\" data-elementor-type=\"wp-page\">\n<section class=\"elementor-section elementor-top-section elementor-element elementor-element-355a605b elementor-section-height-full elementor-section-boxed elementor-section-height-default elementor-section-items-middle\" data-e-type=\"section\" data-element_type=\"section\" data-id=\"355a605b\" data-particle-mobile-disabled=\"false\" data-particle_enable=\"false\" data-settings=\'{\"background_background\":\"classic\"}\'>\n<div class=\"elementor-background-overlay\"></div>\n<div class=\"elementor-container elementor-column-gap-default\">\n<div class=\"elementor-column elementor-col-16 elementor-top-column elementor-element elementor-element-3901529a\" data-e-type=\"column\" data-element_type=\"column\" data-id=\"3901529a\">\n<div class=\"elementor-widget-wrap\">\n</div>\n</div>\n<div class=\"elementor-column elementor-col-66 elementor-top-column elementor-element elementor-element-7dd42e71\" data-e-type=\"column\" data-element_type=\"column\" data-id=\"7dd42e71\">\n<div class=\"elementor-widget-wrap elementor-element-populated\">\n<div class=\"elementor-element elementor-element-45a69b83 elementor-invisible elementor-widget elementor-widget-heading\" data-e-type=\"widget\" data-element_type=\"widget\" data-id=\"45a69b83\" data-settings=\'{\"_animation\":\"fadeInDown\"}\' data-widget_type=\"heading.default\">\n<div class=\"elementor-widget-container\">\n<h1 class=\"elementor-heading-title elementor-size-default\">Casa Maria</h1> </div>\n</div>\n<div class=\"elementor-element elementor-element-135e2dd3 elementor-widget-laptop__width-initial elementor-invisible elementor-widget elementor-widget-heading\" data-e-type=\"widget\" data-element_type=\"widget\" data-id=\"135e2dd3\" data-settings=\'{\"_animation\":\"fadeInUp\",\"_animation_delay\":200}\' data-widget_type=\"heading.default\">\n<div class=\"elementor-widget-container\">\n<h2 class=\"elementor-heading-title elementor-size-default\">Khi tinh thần ẩm thực Ý sống trọn trong một gian bếp thủ công giữa lòng Sài Gòn\n</h2> </div>\n</div>\n</div>\n</div>\n<div class=\"elementor-column elementor-col-16 elementor-top-column elementor-element elementor-element-641e797e\" data-e-type=\"column\" data-element_type=\"column\" data-id=\"641e797e\">\n<div class=\"elementor-widget-wrap\">\n</div>\n</div>\n</div>\n</section>\n<section class=\"elementor-section elementor-top-section elementor-element elementor-element-ef110fa elementor-section-boxed elementor-section-height-default elementor-section-height-default\" data-e-type=\"section\" data-element_type=\"section\" data-id=\"ef110fa\" data-particle-mobile-disabled=\"false\" data-particle_enable=\"false\" data-settings=\'{\"background_background\":\"gradient\"}\'>\n<div class=\"elementor-container elementor-column-gap-no\">\n<div class=\"elementor-column elementor-col-100 elementor-top-column elementor-element elementor-element-65c48449\" data-e-type=\"column\" data-element_type=\"column\" data-id=\"65c48449\">\n<div class=\"elementor-widget-wrap elementor-element-populated\">\n<section class=\"elementor-section elementor-inner-section elementor-element elementor-element-47eb3c1e elementor-section-content-middle elementor-section-boxed elementor-section-height-default elementor-section-height-default\" data-e-type=\"section\" data-element_type=\"section\" data-id=\"47eb3c1e\" data-particle-mobile-disabled=\"false\" data-particle_enable=\"false\">\n<div class=\"elementor-container elementor-column-gap-default\">\n<div class=\"elementor-column elementor-col-16 elementor-inner-column elementor-element elementor-element-6a1c58a5\" data-e-type=\"column\" data-element_type=\"column\" data-id=\"6a1c58a5\">\n<div class=\"elementor-widget-wrap\">\n</div>\n</div>\n<div class=\"elementor-column elementor-col-66 elementor-inner-column elementor-element elementor-element-57555300\" data-e-type=\"column\" data-element_type=\"column\" data-id=\"57555300\">\n<div class=\"elementor-widget-wrap elementor-element-populated\">\n<div class=\"elementor-element elementor-element-6f2c2951 elementor-hidden-phone elementor-invisible elementor-widget elementor-widget-text-editor\" data-e-type=\"widget\" data-element_type=\"widget\" data-id=\"6f2c2951\" data-settings=\'{\"_animation\":\"fadeInUp\",\"_animation_delay\":400}\' data-widget_type=\"text-editor.default\">\n<div class=\"elementor-widget-container\">\n<p><span style=\"font-weight: 400\">Giữa trung tâm Quận 1 sôi động, nơi nhịp sống thành phố chưa bao giờ chậm lại, </span><b>Moa Moa Pasta Club</b><span style=\"font-weight: 400\"> xuất hiện như một khoảng dừng tinh tế dành cho những ai trân trọng </span><b>ẩm thực Ý nguyên bản</b><span style=\"font-weight: 400\">. Tọa lạc tại </span><b>40E Ngô Đức Kế, phường Bến Nghé</b><span style=\"font-weight: 400\">, chỉ cách phố đi bộ Nguyễn Huệ vài bước chân, Moa Moa không chỉ là một nhà hàng pasta – mà là nơi </span><b>thủ công, kỹ thuật và văn hoá ẩm thực</b><span style=\"font-weight: 400\"> giao thoa trong từng chi tiết.</span></p><p> </p><p><span style=\"font-weight: 400\">Đồng hành cùng dự án này, </span><b>Saigon Horeca</b><span style=\"font-weight: 400\"> không tiếp cận Moa Moa như một công trình bếp thông thường, mà như một </span><b>bài toán không gian – vận hành – trải nghiệm</b><span style=\"font-weight: 400\">, nơi mỗi quyết định thiết kế đều phải phục vụ cho tinh thần </span><i><span style=\"font-weight: 400\">Italiano autentico</span></i><span style=\"font-weight: 400\">.</span><br /><!-- notionvc: 5ac5458e-8a78-44ee-bf03-c2721695c1b4 --></p> </div>\n</div>\n</div>\n</div>\n<div class=\"elementor-column elementor-col-16 elementor-inner-column elementor-element elementor-element-183929b\" data-e-type=\"column\" data-element_type=\"column\" data-id=\"183929b\">\n<div class=\"elementor-widget-wrap\">\n</div>\n</div>\n</div>\n</section>\n<section class=\"elementor-section elementor-inner-section elementor-element elementor-element-5f888614 elementor-section-boxed elementor-section-height-default elementor-section-height-default\" data-e-type=\"section\" data-element_type=\"section\" data-id=\"5f888614\" data-particle-mobile-disabled=\"false\" data-particle_enable=\"false\">\n<div class=\"elementor-container elementor-column-gap-default\">\n<div class=\"elementor-column elementor-col-100 elementor-inner-column elementor-element elementor-element-56424ec8\" data-e-type=\"column\" data-element_type=\"column\" data-id=\"56424ec8\">\n<div class=\"elementor-widget-wrap elementor-element-populated\">\n<div class=\"elementor-element elementor-element-24de6da1 elementor-arrows-position-inside elementor-widget elementor-widget-image-carousel\" data-e-type=\"widget\" data-element_type=\"widget\" data-id=\"24de6da1\" data-settings=\'{\"slides_to_show\":\"3\",\"navigation\":\"arrows\",\"image_spacing_custom\":{\"unit\":\"px\",\"size\":30,\"sizes\":[]},\"autoplay\":\"yes\",\"pause_on_hover\":\"yes\",\"pause_on_interaction\":\"yes\",\"autoplay_speed\":5000,\"infinite\":\"yes\",\"speed\":500,\"image_spacing_custom_laptop\":{\"unit\":\"px\",\"size\":\"\",\"sizes\":[]},\"image_spacing_custom_tablet\":{\"unit\":\"px\",\"size\":\"\",\"sizes\":[]},\"image_spacing_custom_mobile\":{\"unit\":\"px\",\"size\":\"\",\"sizes\":[]}}\' data-widget_type=\"image-carousel.default\">\n<div class=\"elementor-widget-container\">\n<div aria-label=\"Băng chuyền hình ảnh\" class=\"elementor-image-carousel-wrapper swiper\" dir=\"ltr\" role=\"region\">\n<div aria-live=\"off\" class=\"elementor-image-carousel swiper-wrapper swiper-image-stretch\">\n<div aria-label=\"1 trên 4\" class=\"swiper-slide\" role=\"group\"><figure class=\"swiper-slide-inner\"><img alt=\"sheh-fung (6)\" class=\"swiper-slide-image\" data-src=\"http://saigonhoreca.local/wp-content/uploads/2025/01/sheh-fung-6.jpg\" src=\"image/svg+xml;base64,PHN2ZyB3aWR0aD0iMSIgaGVpZ2h0PSIxIiB4bWxucz0iaHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmciPjwvc3ZnPg==\" style=\"--smush-placeholder-width: 600px;--smush-placeholder-aspect-ratio: 600/800\" /></figure></div><div aria-label=\"2 trên 4\" class=\"swiper-slide\" role=\"group\"><figure class=\"swiper-slide-inner\"><img alt=\"sheh-fung (8)\" class=\"swiper-slide-image\" data-src=\"http://saigonhoreca.local/wp-content/uploads/2025/01/sheh-fung-8.jpg\" src=\"image/svg+xml;base64,PHN2ZyB3aWR0aD0iMSIgaGVpZ2h0PSIxIiB4bWxucz0iaHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmciPjwvc3ZnPg==\" style=\"--smush-placeholder-width: 600px;--smush-placeholder-aspect-ratio: 600/800\" /></figure></div><div aria-label=\"3 trên 4\" class=\"swiper-slide\" role=\"group\"><figure class=\"swiper-slide-inner\"><img alt=\"sheh-fung (9)\" class=\"swiper-slide-image\" data-src=\"http://saigonhoreca.local/wp-content/uploads/2025/01/sheh-fung-9.jpg\" src=\"image/svg+xml;base64,PHN2ZyB3aWR0aD0iMSIgaGVpZ2h0PSIxIiB4bWxucz0iaHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmciPjwvc3ZnPg==\" style=\"--smush-placeholder-width: 600px;--smush-placeholder-aspect-ratio: 600/800\" /></figure></div><div aria-label=\"4 trên 4\" class=\"swiper-slide\" role=\"group\"><figure class=\"swiper-slide-inner\"><img alt=\"sheh-fung (7)\" class=\"swiper-slide-image\" data-src=\"http://saigonhoreca.local/wp-content/uploads/2025/01/sheh-fung-7.jpg\" src=\"image/svg+xml;base64,PHN2ZyB3aWR0aD0iMSIgaGVpZ2h0PSIxIiB4bWxucz0iaHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmciPjwvc3ZnPg==\" style=\"--smush-placeholder-width: 600px;--smush-placeholder-aspect-ratio: 600/800\" /></figure></div> </div>\n<div class=\"elementor-swiper-button elementor-swiper-button-prev\" role=\"button\">\n </div>\n<div class=\"elementor-swiper-button elementor-swiper-button-next\" role=\"button\">\n </div>\n</div>\n</div>\n</div>\n</div>\n</div>\n</div>\n</section>\n<section class=\"elementor-section elementor-inner-section elementor-element elementor-element-77aaba77 elementor-section-content-middle elementor-section-boxed elementor-section-height-default elementor-section-height-default\" data-e-type=\"section\" data-element_type=\"section\" data-id=\"77aaba77\" data-particle-mobile-disabled=\"false\" data-particle_enable=\"false\">\n<div class=\"elementor-container elementor-column-gap-default\">\n<div class=\"elementor-column elementor-col-100 elementor-inner-column elementor-element elementor-element-3fb64d6a\" data-e-type=\"column\" data-element_type=\"column\" data-id=\"3fb64d6a\">\n<div class=\"elementor-widget-wrap elementor-element-populated\">\n<div class=\"elementor-element elementor-element-54a7f9ec elementor-widget elementor-widget-text-editor\" data-e-type=\"widget\" data-element_type=\"widget\" data-id=\"54a7f9ec\" data-widget_type=\"text-editor.default\">\n<div class=\"elementor-widget-container\">\n<h2><b>Concept Italiano: Khi bếp không chỉ để nấu, mà để kể câu chuyện</b></h2><p><span style=\"font-weight: 400\">Ẩm thực Ý, đặc biệt là pasta thủ công, luôn đặt </span><b>quy trình chế biến</b><span style=\"font-weight: 400\"> vào vị trí trung tâm. Tại Moa Moa, bếp không bị giấu sau những bức tường kín, mà trở thành </span><b>trái tim của nhà hàng</b><span style=\"font-weight: 400\"> – nơi thực khách có thể cảm nhận nhịp điệu làm bếp, từ trộn bột, cán mì, trụng pasta cho đến hoàn thiện món ăn.</span></p><p><span style=\"font-weight: 400\">Vì vậy, layout bếp được SGH tư vấn theo định hướng </span><b>Italian open-kitchen</b><span style=\"font-weight: 400\">: gọn gàng, mạch lạc, phân khu rõ ràng nhưng vẫn đảm bảo dòng di chuyển mượt mà. Không gian bếp phải đủ “mở” để kết nối với khu phục vụ, nhưng đồng thời đủ “chuẩn” để đáp ứng yêu cầu kỹ thuật của một nhà hàng pasta chuyên nghiệp.</span></p><h3><!-- notionvc: 2cb497a8-055a-4db3-9eb5-c31bfb6ed7d7 --></h3> </div>\n</div>\n</div>\n</div>\n</div>\n</section>\n<div class=\"elementor-element elementor-element-e7396e0 e-con-full e-flex e-con e-parent\" data-e-type=\"container\" data-element_type=\"container\" data-id=\"e7396e0\" data-particle-mobile-disabled=\"false\" data-particle_enable=\"false\">\n<div class=\"elementor-element elementor-element-49682e6 elementor-widget elementor-widget-image\" data-e-type=\"widget\" data-element_type=\"widget\" data-id=\"49682e6\" data-widget_type=\"image.default\">\n<div class=\"elementor-widget-container\">\n<img alt=\"Thiết bị bếp công nghiệp Saigon Horeca\" class=\"attachment-large size-large wp-image-24259\" height=\"768\" src=\"http://saigonhoreca.local/wp-content/uploads/2026/03/du-an-thecheezytime-11.jpg\" width=\"1366\" /> </div>\n</div>\n</div>\n<div class=\"elementor-element elementor-element-60d4310 elementor-widget elementor-widget-heading\" data-e-type=\"widget\" data-element_type=\"widget\" data-id=\"60d4310\" data-widget_type=\"heading.default\">\n<div class=\"elementor-widget-container\">\n<span class=\"elementor-heading-title elementor-size-default\">Thiết kế layout: Tối ưu vận hành cho pasta thủ công\n</span> </div>\n</div>\n<div class=\"elementor-element elementor-element-d607033 elementor-widget elementor-widget-text-editor\" data-e-type=\"widget\" data-element_type=\"widget\" data-id=\"d607033\" data-widget_type=\"text-editor.default\">\n<div class=\"elementor-widget-container\">\n<p><span style=\"font-weight: 400\">Khác với nhiều mô hình Âu tổng hợp, bếp pasta đòi hỏi sự </span><b>liền mạch giữa các công đoạn</b><span style=\"font-weight: 400\">. Từ khu trộn bột, chế biến pasta tươi, trụng mì đến khu hoàn thiện món – tất cả phải được bố trí theo một trục logic, giảm thao tác thừa và đảm bảo nhịp độ phục vụ trong giờ cao điểm.</span></p><p><span style=\"font-weight: 400\">Saigon Horeca đã xây dựng layout xoay quanh </span><b>thói quen vận hành thực tế của đầu bếp Ý</b><span style=\"font-weight: 400\">, ưu tiên sự thuận tay, khoảng cách thao tác ngắn và khả năng làm việc liên tục. Đây chính là yếu tố giúp Moa Moa duy trì chất lượng món ăn ổn định, dù nằm giữa một trong những khu vực đông khách nhất TP.HCM.</span></p> </div>\n</div>\n</div>\n</div>\n</div>\n</section>\n<section class=\"elementor-section elementor-top-section elementor-element elementor-element-2fcbcb7f elementor-section-content-middle elementor-section-boxed elementor-section-height-default elementor-section-height-default\" data-e-type=\"section\" data-element_type=\"section\" data-id=\"2fcbcb7f\" data-particle-mobile-disabled=\"false\" data-particle_enable=\"false\" data-settings=\'{\"background_background\":\"classic\"}\'>\n<div class=\"elementor-container elementor-column-gap-default\">\n<div class=\"elementor-column elementor-col-50 elementor-top-column elementor-element elementor-element-2530f256\" data-e-type=\"column\" data-element_type=\"column\" data-id=\"2530f256\">\n<div class=\"elementor-widget-wrap elementor-element-populated\">\n<div class=\"elementor-element elementor-element-31185654 elementor-widget elementor-widget-heading\" data-e-type=\"widget\" data-element_type=\"widget\" data-id=\"31185654\" data-widget_type=\"heading.default\">\n<div class=\"elementor-widget-container\">\n<h2 class=\"elementor-heading-title elementor-size-default\">Hệ thống bếp Âu cao cấp – Nền tảng cho chất lượng món Ý\n</h2> </div>\n</div>\n<div class=\"elementor-element elementor-element-2192d897 elementor-widget-divider--view-line elementor-widget elementor-widget-divider\" data-e-type=\"widget\" data-element_type=\"widget\" data-id=\"2192d897\" data-widget_type=\"divider.default\">\n<div class=\"elementor-widget-container\">\n<div class=\"elementor-divider\">\n<span class=\"elementor-divider-separator\">\n</span>\n</div>\n</div>\n</div>\n<div class=\"elementor-element elementor-element-6cc5680f elementor-widget elementor-widget-text-editor\" data-e-type=\"widget\" data-element_type=\"widget\" data-id=\"6cc5680f\" data-widget_type=\"text-editor.default\">\n<div class=\"elementor-widget-container\">\n<p><span style=\"font-weight: 400\">Trung tâm của gian bếp là </span><b>bếp Âu 6 họng</b><span style=\"font-weight: 400\">, cho phép xử lý đồng thời nhiều món pasta với yêu cầu nhiệt độ khác nhau – yếu tố then chốt trong ẩm thực Ý. Bên cạnh đó, </span><b>nồi trụng mì chuyên dụng</b><span style=\"font-weight: 400\"> được bố trí hợp lý, giúp pasta luôn đạt độ </span><i><span style=\"font-weight: 400\">al dente</span></i><span style=\"font-weight: 400\"> chuẩn mực, không bị gián đoạn trong giờ cao điểm.</span></p><p> </p><p><span style=\"font-weight: 400\">Khu </span><b>bàn trộn bột và chế biến pasta tươi</b><span style=\"font-weight: 400\"> được thiết kế như một “xưởng thủ công thu nhỏ”, nơi đầu bếp có đủ không gian thao tác, kiểm soát độ ẩm, nhiệt độ và kết cấu bột – những yếu tố quyết định linh hồn của pasta tươi.</span></p><p> </p> </div>\n</div>\n</div>\n</div>\n<div class=\"elementor-column elementor-col-50 elementor-top-column elementor-element elementor-element-3cd70efa\" data-e-type=\"column\" data-element_type=\"column\" data-id=\"3cd70efa\">\n<div class=\"elementor-widget-wrap elementor-element-populated\">\n<div class=\"elementor-background-overlay\"></div>\n<div class=\"elementor-element elementor-element-8c54e16 elementor-widget elementor-widget-image\" data-e-type=\"widget\" data-element_type=\"widget\" data-id=\"8c54e16\" data-widget_type=\"image.default\">\n<div class=\"elementor-widget-container\">\n<img alt=\"Thiết bị bếp công nghiệp Saigon Horeca\" class=\"attachment-large size-large wp-image-20871\" data-sizes=\"(max-width: 1366px) 100vw, 1366px\" data-src=\"http://saigonhoreca.local/wp-content/uploads/2025/01/sheh-fung-2.jpg\" data-srcset=\"http://saigonhoreca.local/wp-content/uploads/2025/01/sheh-fung-2.jpg 1366w, http://saigonhoreca.local/wp-content/uploads/2025/01/sheh-fung-2-768x432.jpg 768w, http://saigonhoreca.local/wp-content/uploads/2025/01/sheh-fung-2-600x337.jpg 600w\" height=\"768\" src=\"image/svg+xml;base64,PHN2ZyB3aWR0aD0iMSIgaGVpZ2h0PSIxIiB4bWxucz0iaHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmciPjwvc3ZnPg==\" style=\"--smush-placeholder-width: 1366px;--smush-placeholder-aspect-ratio: 1366/768\" width=\"1366\" /> </div>\n</div>\n<div class=\"elementor-element elementor-element-1cb4af97 elementor-widget elementor-widget-image\" data-e-type=\"widget\" data-element_type=\"widget\" data-id=\"1cb4af97\" data-widget_type=\"image.default\">\n<div class=\"elementor-widget-container\">\n<figure class=\"wp-caption\">\n<img alt=\"Thiết bị bếp công nghiệp Saigon Horeca\" class=\"attachment-large size-large wp-image-20872\" data-sizes=\"(max-width: 1366px) 100vw, 1366px\" data-src=\"http://saigonhoreca.local/wp-content/uploads/2025/01/sheh-fung-3.jpg\" data-srcset=\"http://saigonhoreca.local/wp-content/uploads/2025/01/sheh-fung-3.jpg 1366w, http://saigonhoreca.local/wp-content/uploads/2025/01/sheh-fung-3-768x432.jpg 768w, http://saigonhoreca.local/wp-content/uploads/2025/01/sheh-fung-3-600x337.jpg 600w\" height=\"768\" src=\"image/svg+xml;base64,PHN2ZyB3aWR0aD0iMSIgaGVpZ2h0PSIxIiB4bWxucz0iaHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmciPjwvc3ZnPg==\" style=\"--smush-placeholder-width: 1366px;--smush-placeholder-aspect-ratio: 1366/768\" width=\"1366\" /> <figcaption class=\"widget-image-caption wp-caption-text\">Thiết kế bếp khoa học,  thiết bị bếp tối tân được cung cấp bởi Saigon Horeca</figcaption>\n</figure>\n</div>\n</div>\n</div>\n</div>\n</div>\n</section>\n<section class=\"elementor-section elementor-top-section elementor-element elementor-element-16b4144a elementor-section-content-middle elementor-section-boxed elementor-section-height-default elementor-section-height-default\" data-e-type=\"section\" data-element_type=\"section\" data-id=\"16b4144a\" data-particle-mobile-disabled=\"false\" data-particle_enable=\"false\" data-settings=\'{\"background_background\":\"classic\"}\'>\n<div class=\"elementor-container elementor-column-gap-default\">\n<div class=\"elementor-column elementor-col-50 elementor-top-column elementor-element elementor-element-4fc0aebb\" data-e-type=\"column\" data-element_type=\"column\" data-id=\"4fc0aebb\">\n<div class=\"elementor-widget-wrap elementor-element-populated\">\n<div class=\"elementor-background-overlay\"></div>\n<div class=\"elementor-element elementor-element-44cfec72 elementor-widget elementor-widget-image\" data-e-type=\"widget\" data-element_type=\"widget\" data-id=\"44cfec72\" data-widget_type=\"image.default\">\n<div class=\"elementor-widget-container\">\n<figure class=\"wp-caption\">\n<img alt=\"Bếp á đôi công nghiệp\" class=\"attachment-large size-large wp-image-20879\" data-sizes=\"(max-width: 1366px) 100vw, 1366px\" data-src=\"http://saigonhoreca.local/wp-content/uploads/2025/01/sheh-fung-4.jpg\" data-srcset=\"http://saigonhoreca.local/wp-content/uploads/2025/01/sheh-fung-4.jpg 1366w, http://saigonhoreca.local/wp-content/uploads/2025/01/sheh-fung-4-768x432.jpg 768w, http://saigonhoreca.local/wp-content/uploads/2025/01/sheh-fung-4-600x337.jpg 600w\" height=\"768\" src=\"image/svg+xml;base64,PHN2ZyB3aWR0aD0iMSIgaGVpZ2h0PSIxIiB4bWxucz0iaHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmciPjwvc3ZnPg==\" style=\"--smush-placeholder-width: 1366px;--smush-placeholder-aspect-ratio: 1366/768\" width=\"1366\" /> <figcaption class=\"widget-image-caption wp-caption-text\">Hệ thống hút mùi và cấp gió tươi cho bếp canteen Sheh Fung</figcaption>\n</figure>\n</div>\n</div>\n</div>\n</div>\n<div class=\"elementor-column elementor-col-50 elementor-top-column elementor-element elementor-element-515501e0\" data-e-type=\"column\" data-element_type=\"column\" data-id=\"515501e0\">\n<div class=\"elementor-widget-wrap elementor-element-populated\">\n<div class=\"elementor-element elementor-element-c4c2185 elementor-widget elementor-widget-heading\" data-e-type=\"widget\" data-element_type=\"widget\" data-id=\"c4c2185\" data-widget_type=\"heading.default\">\n<div class=\"elementor-widget-container\">\n<span class=\"elementor-heading-title elementor-size-default\">Hệ thống hút khói – xử lý mùi: Giữ trọn trải nghiệm giữa phố đi bộ\n</span> </div>\n</div>\n<div class=\"elementor-element elementor-element-2415dca5 elementor-widget-divider--view-line elementor-widget elementor-widget-divider\" data-e-type=\"widget\" data-element_type=\"widget\" data-id=\"2415dca5\" data-widget_type=\"divider.default\">\n<div class=\"elementor-widget-container\">\n<div class=\"elementor-divider\">\n<span class=\"elementor-divider-separator\">\n</span>\n</div>\n</div>\n</div>\n<div class=\"elementor-element elementor-element-28e5fb6b elementor-widget elementor-widget-text-editor\" data-e-type=\"widget\" data-element_type=\"widget\" data-id=\"28e5fb6b\" data-widget_type=\"text-editor.default\">\n<div class=\"elementor-widget-container\">\n<p><span style=\"font-weight: 400\">Với mô hình bếp mở và vị trí đắc địa ngay khu phố đi bộ Nguyễn Huệ, bài toán lớn nhất của Moa Moa không chỉ là nấu ngon, mà còn là </span><b>kiểm soát mùi và khói</b><span style=\"font-weight: 400\">.</span></p><p> </p><p><span style=\"font-weight: 400\">Saigon Horeca đã cung cấp và lắp đặt </span><b>hệ thống chụp hút và quạt hút chuyên dụng</b><span style=\"font-weight: 400\">, được tính toán kỹ lưỡng theo công suất thiết bị và đặc thù bếp Âu – bếp nướng than củi. Hệ thống này đảm bảo không gian bếp luôn thông thoáng, không ảnh hưởng đến trải nghiệm thực khách, đồng thời tuân thủ các tiêu chuẩn an toàn – vận hành trong khu vực trung tâm đông đúc.</span></p> </div>\n</div>\n</div>\n</div>\n</div>\n</section>\n<section class=\"elementor-section elementor-top-section elementor-element elementor-element-8834001 elementor-section-content-middle elementor-section-boxed elementor-section-height-default elementor-section-height-default\" data-e-type=\"section\" data-element_type=\"section\" data-id=\"8834001\" data-particle-mobile-disabled=\"false\" data-particle_enable=\"false\" data-settings=\'{\"background_background\":\"classic\"}\'>\n<div class=\"elementor-container elementor-column-gap-default\">\n<div class=\"elementor-column elementor-col-100 elementor-top-column elementor-element elementor-element-549d58a\" data-e-type=\"column\" data-element_type=\"column\" data-id=\"549d58a\">\n<div class=\"elementor-widget-wrap elementor-element-populated\">\n<div class=\"elementor-element elementor-element-b5b691c elementor-widget-divider--view-line elementor-widget elementor-widget-divider\" data-e-type=\"widget\" data-element_type=\"widget\" data-id=\"b5b691c\" data-widget_type=\"divider.default\">\n<div class=\"elementor-widget-container\">\n<div class=\"elementor-divider\">\n<span class=\"elementor-divider-separator\">\n</span>\n</div>\n</div>\n</div>\n<div class=\"elementor-element elementor-element-804b825 elementor-widget elementor-widget-heading\" data-e-type=\"widget\" data-element_type=\"widget\" data-id=\"804b825\" data-widget_type=\"heading.default\">\n<div class=\"elementor-widget-container\">\n<span class=\"elementor-heading-title elementor-size-default\">Thiết bị lạnh &amp; lưu trữ: Giữ trọn độ tươi cho từng nguyên liệu\n</span> </div>\n</div>\n<div class=\"elementor-element elementor-element-cdc436f elementor-widget elementor-widget-text-editor\" data-e-type=\"widget\" data-element_type=\"widget\" data-id=\"cdc436f\" data-widget_type=\"text-editor.default\">\n<div class=\"elementor-widget-container\">\n<p><span style=\"font-weight: 400\">Ẩm thực Ý đề cao </span><b>nguyên liệu tươi và xử lý nhanh</b><span style=\"font-weight: 400\">. Vì vậy, Moa Moa sử dụng </span><b>tủ đông – tủ mát dạng ngăn kéo</b><span style=\"font-weight: 400\">, cho phép đầu bếp lấy nguyên liệu ngay tại vị trí thao tác mà không phá vỡ nhịp làm việc. Đây là chi tiết nhỏ nhưng thể hiện rõ tư duy thiết kế bếp theo hướng </span><b>lấy con người và quy trình làm trung tâm</b><span style=\"font-weight: 400\">.</span></p> </div>\n</div>\n<div class=\"elementor-element elementor-element-13f4146 elementor-widget elementor-widget-image\" data-e-type=\"widget\" data-element_type=\"widget\" data-id=\"13f4146\" data-widget_type=\"image.default\">\n<div class=\"elementor-widget-container\">\n<img alt=\"Thiết bị bếp công nghiệp Saigon Horeca\" class=\"attachment-large size-large wp-image-20074\" data-sizes=\"(max-width: 1366px) 100vw, 1366px\" data-src=\"http://saigonhoreca.local/wp-content/uploads/2023/12/bi-quyet-tao-thuc-don-nha-hang.jpg\" data-srcset=\"http://saigonhoreca.local/wp-content/uploads/2023/12/bi-quyet-tao-thuc-don-nha-hang.jpg 1366w, http://saigonhoreca.local/wp-content/uploads/2023/12/bi-quyet-tao-thuc-don-nha-hang-768x432.jpg 768w, http://saigonhoreca.local/wp-content/uploads/2023/12/bi-quyet-tao-thuc-don-nha-hang-600x337.jpg 600w\" height=\"768\" src=\"image/svg+xml;base64,PHN2ZyB3aWR0aD0iMSIgaGVpZ2h0PSIxIiB4bWxucz0iaHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmciPjwvc3ZnPg==\" style=\"--smush-placeholder-width: 1366px;--smush-placeholder-aspect-ratio: 1366/768\" width=\"1366\" /> </div>\n</div>\n<div class=\"elementor-element elementor-element-ad4b133 elementor-widget elementor-widget-heading\" data-e-type=\"widget\" data-element_type=\"widget\" data-id=\"ad4b133\" data-widget_type=\"heading.default\">\n<div class=\"elementor-widget-container\">\n<span class=\"elementor-heading-title elementor-size-default\">Saigon Horeca – Đối tác đứng sau một gian bếp “đúng chất Ý”\n</span> </div>\n</div>\n<div class=\"elementor-element elementor-element-5731de4 elementor-widget elementor-widget-text-editor\" data-e-type=\"widget\" data-element_type=\"widget\" data-id=\"5731de4\" data-widget_type=\"text-editor.default\">\n<div class=\"elementor-widget-container\">\n<p><span style=\"font-weight: 400\">Dự án Moa Moa không đơn thuần là việc cung cấp thiết bị. Đó là quá trình </span><b>tư vấn – thiết kế – lắp đặt</b><span style=\"font-weight: 400\"> dựa trên sự thấu hiểu mô hình pasta restaurant, văn hoá ẩm thực Ý và áp lực vận hành thực tế tại trung tâm TP.HCM.</span></p><p><span style=\"font-weight: 400\">Với Moa Moa, Saigon Horeca tiếp tục khẳng định vai trò của mình: </span><b>không chỉ xây bếp, mà kiến tạo nền tảng để ẩm thực được kể đúng câu chuyện của nó</b><span style=\"font-weight: 400\">.</span></p> </div>\n</div>\n</div>\n</div>\n</div>\n</section>\n<section class=\"elementor-section elementor-inner-section elementor-element elementor-element-3c996186 elementor-section-boxed elementor-section-height-default elementor-section-height-default\" data-e-type=\"section\" data-element_type=\"section\" data-id=\"3c996186\" data-particle-mobile-disabled=\"false\" data-particle_enable=\"false\">\n<div class=\"elementor-container elementor-column-gap-default\">\n<div class=\"elementor-column elementor-col-33 elementor-inner-column elementor-element elementor-element-3bf6642a\" data-e-type=\"column\" data-element_type=\"column\" data-id=\"3bf6642a\" data-settings=\'{\"background_background\":\"classic\"}\'>\n<div class=\"elementor-widget-wrap elementor-element-populated\">\n<div class=\"elementor-element elementor-element-52ee5429 elementor-view-default elementor-position-block-start elementor-mobile-position-block-start elementor-widget elementor-widget-icon-box\" data-e-type=\"widget\" data-element_type=\"widget\" data-id=\"52ee5429\" data-widget_type=\"icon-box.default\">\n<div class=\"elementor-widget-container\">\n<div class=\"elementor-icon-box-wrapper\">\n<div class=\"elementor-icon-box-icon\">\n<span class=\"elementor-icon\">\n </span>\n</div>\n<div class=\"elementor-icon-box-content\">\n<h3 class=\"elementor-icon-box-title\">\n<span>\n							+84 901 304 365						</span>\n</h3>\n<p class=\"elementor-icon-box-description\">\n						Thứ 2 - Thứ 6 <br />từ 8h00 - 18h00					</p>\n</div>\n</div>\n</div>\n</div>\n<div class=\"elementor-element elementor-element-4804355e elementor-align-center elementor-mobile-align-center elementor-widget elementor-widget-button\" data-e-type=\"widget\" data-element_type=\"widget\" data-id=\"4804355e\" data-widget_type=\"button.default\">\n<div class=\"elementor-widget-container\">\n<div class=\"elementor-button-wrapper\">\n<a class=\"elementor-button elementor-button-link elementor-size-sm\" href=\"tel:8