INSERT INTO `wp_posts` VALUES (1870,0,'2026-05-20 02:40:38','2026-05-20 02:40:38','<p><strong>Rokafella</strong> — dự án thiết kế và thi công hệ thống bếp, quầy bar bởi Saigon Horeca. Không gian F&amp;B cao cấp tại TP.HCM với phong cách contemporary kết hợp ẩm thực sáng tạo.</p>','Rokafella','Dự án Rokafella — thiết kế bếp và quầy bar bởi Saigon Horeca.','inherit','closed','closed','','1868-revision-v1','','','2026-05-20 02:40:38','2026-05-20 02:40:38','',1868,'https://saigonhoreca.local/?p=1870',0,'revision','',0);
