INSERT INTO `wp_posts` VALUES (1913,0,'2026-05-20 09:25:57','2026-05-20 09:25:57','<p>Máy Ép Trái Cây Công Nghiệp LI-240 &#8211; Sammic-Spain là sản phẩm cao cấp được thiết kế chuyên dụng để ép trái cây, rau củ quả lấy nước. Máy có công suất lớn, khả năng ép nhanh chóng và hiệu quả, cùng với thiết kế hiện đại, sang trọng, sẽ là lựa chọn hoàn hảo cho các nhà hàng, quán ăn, quán cà phê, hoặc những người yêu thích làm nước ép trái cây.</p>\n<p>Máy có công suất lên đến 240W, giúp bạn ép trái cây nhanh chóng và hiệu quả.</p>\n<p>Máy có thể ép được nhiều loại trái cây và rau củ quả khác nhau như cam, táo, cà rốt, &#8230;</p>\n<p>Máy được làm bằng thép không gỉ cao cấp, bền bỉ, dễ dàng vệ sinh.</p>\n<p>Tính năng tiện lợi: Máy có vòi chảy tự động giúp bạn dễ dàng lấy nước ép. Máy cũng có chức năng tự ngắt khi quá tải giúp bảo vệ động cơ.</p>\n','Máy Ép LI-240 – Sammic-Spain','Máy Ép Trái Cây Công Nghiệp LI-240 – Sammic-Spain là sản phẩm cao cấp được thiết kế chuyên dụng để ép trái cây, rau củ quả lấy nước. Máy có công suất lớn, khả năng ép nhanh chóng và hiệu quả, cùng với thiết kế hiện đại, sang trọng, sẽ là lựa chọn hoàn hảo cho các nhà hàng, quán ăn, quán cà phê, hoặc những người yêu thích làm nước ép trái cây.\nMáy có công suất lên đến 240W, giúp bạn ép trái cây nhanh chóng và hiệu quả.\nMáy có thể ép được nhiều loại trái cây và rau củ quả khác nhau như cam, táo, cà rốt, …\nMáy được làm bằng thép không gỉ cao cấp, bền bỉ, dễ dàng vệ sinh.\nTính năng tiện lợi: Máy có vòi chảy tự động giúp bạn dễ dàng lấy nước ép. Máy cũng có chức năng tự ngắt khi quá tải giúp bảo vệ động cơ.','inherit','closed','closed','','595-revision-v1','','','2026-05-20 09:25:57','2026-05-20 09:25:57','',595,'https://saigonhoreca.local/?p=1913',0,'revision','',0);
INSERT INTO `wp_posts` VALUES (1914,0,'2026-05-20 09:25:58','2026-05-20 09:25:58','<div class=\"ast-accordion-wrap\"><p>Kích thước: 384x465x403 (mm)<br /> KT khoang: 330x360x155 (mm)<br /> KT hàn miệng: 1 x 320 mm<br /> Trọng lượng: 34 kg<br /> Công suất: 10m3/h<br /> Công suất điện: 370 W<br /> Áp lực chân không tối đa: 2 mbar<br /> Khí trơ (inert gas)<br /> Điện áp: 230V/50-60Hz/1P<br /> Xuất xứ: Spain</p>\n</div>\n</div>\n</div>\n<div class=\"ast-single-tab\"><h3 class=\"ast-accordion-header ast-tab-header\"> Additional information <span aria-hidden=\"true\" class=\"ahfb-svg-iconset ast-inline-flex\"></span><span aria-hidden=\"true\" class=\"ahfb-svg-iconset ast-inline-flex\"></span></h3>\n<div class=\"ast-accordion-content woocommerce-Tabs-panel woocommerce-Tabs-panel--additional_information panel entry-content wc-tab\" role=\"tabpanel\" aria-labelledby=\"tab-title-additional_information\"><div class=\"ast-accordion-wrap\"><table class=\"woocommerce-product-attributes shop_attributes\" aria-label=\"Product Details\"><tr class=\"woocommerce-product-attributes-item woocommerce-product-attributes-item--attribute_th%c6%b0%c6%a1ng-hi%e1%bb%87u\"><th class=\"woocommerce-product-attributes-item__label\" scope=\"row\">Thương Hiệu</th><td class=\"woocommerce-product-attributes-item__value\"><p>Sammic-Spain</p>\n</td></tr>\n</table>\n</div>\n</div>\n</div>\n<div class=\"ast-single-tab\"><h3 class=\"ast-accordion-header ast-tab-header\"> Reviews (0) <span aria-hidden=\"true\" class=\"ahfb-svg-iconset ast-inline-flex\"></span><span aria-hidden=\"true\" class=\"ahfb-svg-iconset ast-inline-flex\"></span></h3>\n<div class=\"ast-accordion-content woocommerce-Tabs-panel woocommerce-Tabs-panel--reviews panel entry-content wc-tab\" role=\"tabpanel\" aria-labelledby=\"tab-title-reviews\"><div class=\"ast-accordion-wrap\"><div class=\"woocommerce-Reviews\"><div><h2 class=\"woocommerce-Reviews-title\"> Reviews </h2>\n<p class=\"woocommerce-noreviews\">There are no reviews yet.</p>\n<