INSERT INTO `wp_posts` VALUES (2068,0,'2026-05-20 09:33:19','2026-05-20 09:33:19','<div class=\"ast-accordion-wrap\"><h2>Mô tả thông số kỹ thuật của Máy hút chân không SU-420 – Sammic</h2>\n<p class=\"legend\">Tabletop model. 20 m³/h. 420 mm.</p>\n<h4>Specifications Sheet</h4>\n<p>Pump capacity: 20 m³/h<br> Pump capacity (60 Hz): 24 m³/h<br> Bar length: 420 mm<br> Total loading: 750 W<br> Vacuum pressure (maximum): 2 mbar</p>\n<p>Plug: —</p>\n<p><strong>Internal dimensions</strong></p>\n<ul><li>Width: 430 mm</li>\n<li>Depth: 415 mm</li>\n<li>Height: 180 mm</li>\n</ul>\n<p><strong>External dimensions (WxDxH)</strong></p>\n<ul><li>Width: 484 mm</li>\n<li>Depth: 529 mm</li>\n<li>Height: 448 mm (230V) / 529 mm (120V)</li>\n<li>Depth: 529 mm</li>\n<li>Height: 448 mm</li>\n</ul>\n<p>Net weight: 56.7 Kg</p>\n<p>Noise level (1m.): 75 dB(A)<br> Background noise: 32 dB(A)</p>\n<p><strong>Crated dimensions</strong><br> 600 x 600 x 610 mm<br> Gross weight: 62.7 Kg</p>\n<p><img class=\"alignnone wp-image-14517 size-full\" alt=\"Máy hút chân không SU-420 – Sammic\" width=\"510\" height=\"510\" src=\"image/svg+xml;base64,PHN2ZyB3aWR0aD0iMSIgaGVpZ2h0PSIxIiB4bWxucz0iaHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmciPjwvc3ZnPg==\"></p>\n<h4>Default equipment</h4>\n<ul><li>BUSCH pump.</li>\n<li>Sensor controls.</li>\n<li>Programmable.</li>\n<li>Vacuum PLUS: up to 10 seconds of extra vacuum pull.</li>\n<li>Soft air function.</li>\n<li>Clear methacrylate lid.</li>\n<li>“PAUSE” function.</li>\n<li>Liquid detection system.</li>\n<li>Dry oil cycle.</li>\n<li>NSF approved.</li>\n<li>Filling plate.</li>\n</ul>\n<h4>Optional equipment</h4>\n<ul><li>Inert gas</li>\n<li>Sealing plus</li>\n<li>Printer</li>\n<li>Bluetooth connectivity</li>\n<li>Vacuum packing bags</li>\n<li>External vacuum kit for Vac-Norm, containers and accessories</li>\n<li>Support for liquid packaging</li>\n<li>Additional filling plates</li>\n</ul>\n</div>\n','Máy hút chân không SU-420 – Sammic','','inherit','closed','closed','','1588-revision-v1','','','2026-05-20 09:33:19','2026-05-20 09:33:19','',1588,'https://saigonhoreca.local/?p=2068',0,'revision','',0);
INSERT INTO `wp_posts` VALUES (2069,0,'2026-05-20 09:34:18','2026-05-20 09:34:18','<div class=\"ast-accordion-wrap\"><h2>Mô tả thông số kỹ thuật của Bàn đông FT-126MA-S – Hoshizaki</h2>\n<table class=\"specifications\"><tbody><tr><td>Product Series</td><td>UNDERCOUNTER, Freezer</td></tr>\n<tr><td>Model Name</td><td>FT-126MA-S</td></tr>\n<tr><td>Net Weight (kg)</td><td>72</td></tr>\n<tr><td>Gross Weight Packed (kg)</td><td>77</td></tr>\n<tr><td>Electric Connection Load (kW)</td><td>0.41</td></tr>\n<tr><td>Outside Dimensions W x D x H (mm)</td><td>1200 x 600 x 850</td></tr>\n<tr><td>Refrigerant</td><td>R404A</td></tr>\n<tr><td>Temperature setting</td><td>-23°C to -7°C</td></tr>\n<tr><td>Effective Storage Capacity (L)</td><td>231</td></tr>\n<tr><td>Number of Shelves (Pcs)</td><td>4</td></tr>\n<tr><td>Cooling System</td><td>Air Cooled</td></tr>\n</tbody></table>\n<p><img class=\"alignnone size-full wp-image-14450\" alt=\"Bàn đông FT-126MA-S - Hoshizaki\" width=\"500\" height=\"600\" src=\"image/svg+xml;base64,PHN2ZyB3aWR0aD0iMSIgaGVpZ2h0PSIxIiB4bWxucz0iaHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmciPjwvc3ZnPg==\"></p>\n</div>\n','Bàn đông FT-126MA-S – Hoshizaki','Bàn đông UNDERCOUNTER FREEZER FT-126MA-S – Hoshizaki\nCác tủ A-FIT được thiết kế để thể hiện hiệu suất vượt trội và độ bền bỉ, dựa trên kinh nghiệm lâu năm của Hoshizaki. Thiết bị bàn đông FT-126MA-S – Hoshizaki mới này kết hợp thiết kế tiện dụng với chức năng cao và công suất làm lạnh mạnh mẽ, đáp ứng mọi nhu cầu khắt khe của khách hàng.','inherit','closed','closed','','555-revision-v1','','','2026-05-20 09:34:18','2026-05-20 09:34:18','',555,'https://saigonhoreca.local/?p=2069',0,'revision','',0);
INSERT INTO `wp_posts` VALUES (2070,0,'2026-05-20 09:34:19','2026-05-20 09:34:19','<div class=\"ast-accordion-wrap\"><p>Kích thước (mm): 1500x600x850<br> Trọng lượng (kg): 107<br> Kết nối điện (V): 3/380<br> Công suất (kW): 1.50<br> Controllable temperature range：30-1100C<br> Công nghệ: Japan<br> Xuất xứ: Việt Nam</p>\n</div>\n','Bàn Giữ Ấm Chén Dĩa FHT1560 – Fujimak-Japan','Bàn Giữ Ấm Chén Dĩa FHT1560 – Fujimak-Japan là sản phẩm được sản xuất bởi thương hiệu Fujimak nổi tiếng của Nhật Bản. Bàn được thiết kế với 2 tầng, sử dụng công nghệ sấy khô bằng tia UV, giúp giữ ấm chén dĩa và khử trùng hiệu quả.\nBàn sử dụng công nghệ sấy khô bằng tia UV giúp giữ ấm chén dĩa trong thời gian dài.\nCó thể điều chỉnh nhiệt độ phù hợp với nhu cầu sử dụng.\nTia UV giúp khử trùng chén dĩa, loại bỏ 99,99% vi khuẩn và nấm mốc.\nGiúp đảm bảo an toàn cho sức khỏe.\nBàn có 2 tầng, dung tích lớn, phù hợp cho nhiều chén dĩa.\nCó thể tháo lắp dễ dàng để vệ sinh.\nBàn có bảng điều khiển đơn giản, dễ dàng sử dụng.\nCó chức năng hẹn giờ giúp bạn chủ động thời gian giữ ấm chén dĩa.','inherit','closed','closed','','556-revision-v1','','','2026-05-20 09:34:19','2026-05-20 09:34:19','',556,'https://saigonhoreca.local/?p=2070',0,'revision','',0);
