INSERT INTO `wp_posts` VALUES (2151,0,'2026-05-20 09:35:01','2026-05-20 09:35:01','<div class=\"ast-accordion-wrap\"><p>Kích thước: 500x450x850 mm<br> Khối lượng tịnh: 42 kg<br> Công suất: 185 W<br> Kết nối điện 1/220V – 240V/50Hz<br> Loại Đá XL Cube – 48<br> Dung tích thừng chứa: 10 kg<br> Năng suất xấp xỉ. 20 Kg/24hrs<br> Xuất xứ: Japan</p>\n</div>\n','Máy Làm Đá Viên Lớn IM-35M-2-LM – Hoshizaki','Máy Làm Đá Viên Lớn IM-35M-2-LM – Hoshizaki đến từ thương hiệu Hoshizaki nổi tiếng Nhật Bản là lựa chọn hoàn hảo cho các doanh nghiệp kinh doanh dịch vụ ăn uống như quán cà phê, nhà hàng, khách sạn,… Máy mang đến những ưu điểm vượt trội:\nViên đá viên lớn tan chậm hơn so với đá viên thông thường, giúp giữ lạnh đồ uống lâu hơn.\nMáy sử dụng công nghệ làm đá tiên tiến, đảm bảo đá viên trong suốt, không lẫn tạp chất.\nMáy được sản xuất theo tiêu chuẩn an toàn vệ sinh thực phẩm quốc tế, đảm bảo đá viên an toàn cho sức khỏe người sử dụng.','inherit','closed','closed','','640-revision-v1','','','2026-05-20 09:35:01','2026-05-20 09:35:01','',640,'https://saigonhoreca.local/?p=2151',0,'revision','',0);
