INSERT INTO `wp_posts_backup_reimport` VALUES (661,'<h2 data-sourcepos=\"1:1-1:55\">Mô tả thông số kỹ thuật của SmartVide XL và 120P heated tank – Sammic</h2>\n<p class=\"legend\">The SmartVide XL cooker + 120P heated tank: Serve up to 200 portions of 200 gr per hour.</p>\n<ul>\n<li><strong>High production: </strong>Up to 200 servings of 200 gr per hour.</li>\n<li><strong>Menu versatility: </strong>Several meals can be retherming simultaneously in the same bath.</li>\n<li><strong>Culinary quality: </strong>Preserves quality of the product and enhances flavor and texture.</li>\n<li><strong>Precision: </strong>To obtain extremely consistent results.</li>\n<li><strong>Easy HACCP control: </strong>Allowing to export or print results of each cycle.</li>\n<li><strong>Janby Trac-Ready: </strong>Control cooking &amp; retherming times of each product independently.</li>\n</ul>\n<p><img alt=\"SmartVide XL và 120P heated tank - Sammic\" class=\"alignnone wp-image-14437 size-full lazyload\" data-src=\"http://saigonhoreca.local/wp-content/uploads/2023/12/smartvide-xl-120p-heated-tank-sammic.jpg\" decoding=\"async\" height=\"600\" src=\"data:image/svg+xml;base64,PHN2ZyB3aWR0aD0iMSIgaGVpZ2h0PSIxIiB4bWxucz0iaHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmciPjwvc3ZnPg==\" style=\"--smush-placeholder-width: 500px; --smush-placeholder-aspect-ratio: 500/600;\" width=\"500\"/></p>');
